fn gcd(mut a: u32, mut b: u32) -> u32 {
    while b != 0 {
        let temp = b;
        b = a % b;
        a = temp;
    }
    a
}

fn is_prime(n: Int) -> Bool {
    if n <= 1 {
        return false
    }
    for i in range(2, n) {
        if n % i == 0 {
            return false
        }
    }
    true
}

fn count_primes(n: Int) -> Int {
    let mut count = 0
    for i in range(2, n) {
        if is_prime(i) {
            count = count + 1
        }
    }
    count
}

fn main() {
    print(count_primes(100))
}

fn main() {
    let n = 100
    let mut i = 0
    let mut primes = vec()
    while i < n {
        let is_prime = is_prime(i)
        if is_prime {
            primes = push(primes, i)
        }
        i = i + 1
    }
    print(primes.len())
}

fn is_prime(n: Int) -> Bool {
    if n == 2 || n == 3 {
        return true
    }
    if n < 2 || n % 2 == 0 || n % 3 == 0 {
        return false
    }
    let mut i = 5
    while i * i <= n {
        if n % i == 0 || n % (i + 2) == 0 {
            return false
        }
        i = i + 6
    }
    true
}

