fn int_to_str(n: Int) -> Str {
    let mut s = vec()
    let mut n = n
    let mut buf = vec()
    while n > 0 {
        let r = n % 10
        buf = push(buf, 48 + r)
        n = n / 10
    }
    let mut buf = reverse(buf)
    while !buf.is_empty() {
        s = push(s, buf.first())
        buf = buf + 1
    }
    s
}

fn reverse(v: Vec<Int>) -> Vec<Int> {
    let mut v = clone(&v)
    let mut i = 0
    let mut j = v.len() - 1
    while i < j {
        let t = v.get(i)
        v.set(i, v.get(j))
        v.set(j, t)
        i = i + 1
        j = j - 1
    }
    v
}

