fn parse_int(s: Str) -> Option<Int> {
    let n = chars(s).len()
    let mut i = 0
    while i < n && s.get(i) == 48 {
        i = i + 1
    }
    if i == n {
        return None
    }
    let mut result = 0
    while i < n {
        let d = s.get(i) - 48
        if d < 0 || d > 9 {
            return None
        }
        result = result * 10 + d
        i = i + 1
    }
    Some(result)
}

fn chars(s: Str) -> Vec<Str> {
    let mut v = vec()
    let n = s.len()
    let mut i = 0
    while i < n {
        v = push(v, s.slice(i, i + 1))
        i = i + 1
    }
    v
}

