    assert_parse_int("1234", 1234)
    assert_parse_int("1234.5", None)
    assert_parse_float("1234.5", 1234.5)
    assert_parse_float("1234.", None)
    assert_parse_bool("true", true)
    assert_parse_bool("false", false)
    assert_parse_bool("1", None)
    assert_parse_str("\"foo\"", "foo")
