    let mut count = 0
    let mut result = vec()
    for value in &list {
        if value > min {
            count = count + 1
            result = push(result, value)
        }
    }
    print_str("Filtered values:")
    for value in &result {
        print(value)
    }
    print_str("Number of values kept:")
    print(count)
    count
}

