fn vec() -> Vec<T> {
    let v = Vec { data: BoxedSlice { data: 0, len: 0 } }
    v
}

fn push(v: Vec<T>, x: T) -> Vec<T> {
    let new_len = v.data.len + 1
    let new_data = BoxedSlice { data: v.data.data, len: new_len }
    let v = Vec { data: new_data }
    v
}

fn len(v: Vec<T>) -> Int {
    v.data.len
}

struct Vec { data: BoxedSlice<T> }

struct BoxedSlice { data: T, len: Int }

fn get(v: Vec<T>, i: Int) -> Option<T> {
    if i >= 0 && i < len(&v) {
        Some(v.data.data + i)
    } else {
        None
    }
}

fn range(a: Int, b: Int) -> Vec<Int> {
    let mut v = vec()
    for i in range(a, b) {
        v = push(v, i)
    }
    v
}

